<template><div><div class="page-head"><div><h1>Payments</h1><p>Record collections and keep invoice balances accurate.</p></div><button class="btn btn-primary" @click="openCreate">+ Receive payment</button></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Receipt</th><th>Client</th><th>Method</th><th>Date</th><th>Amount</th><th>Allocated</th><th class="text-right">Action</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td><RouterLink :to="`/payments/${p.id}`" class="font-bold text-indigo-600">{{p.payment_number}}</RouterLink></td><td>{{p.client?.name||'—'}}</td><td class="capitalize">{{p.method}}</td><td>{{p.payment_date}}</td><td>{{money(p.amount)}}</td><td>{{money(p.allocations?.reduce((s:any,a:any)=>s+Number(a.amount||0),0))}}</td><td class="text-right"><button class="btn btn-danger" @click="remove(p)">Reverse</button></td></tr><tr v-if="!payments.length"><td colspan="7"><div class="empty">No payments recorded.</div></td></tr></tbody></table></div><AppModal :open="open" title="Receive payment" subtitle="Apply the payment to one or more open invoices." @close="open=false"><form @submit.prevent="save"><div class="grid gap-4 md:grid-cols-2"><div><label class="label">Client *</label><select v-model="form.client_id" class="input" @change="loadInvoices" required><option :value="null">Select client</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Amount *</label><MoneyInput v-model="form.amount" :min="0.01" /></div><div><label class="label">Payment method</label><select v-model="form.method" class="input"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mpesa">M-Pesa</option><option value="airtel_money">Airtel Money</option><option value="tigopesa">Mixx by Yas</option><option value="halopesa">HaloPesa</option><option value="card">Card</option><option value="cheque">Cheque</option></select></div><div><label class="label">Reference</label><input v-model="form.reference" class="input" placeholder="Transaction reference"></div></div><div class="mt-5 rounded-2xl border border-slate-100 bg-slate-50/60 p-4"><div class="mb-3 flex justify-between"><div class="text-xs font-bold">Allocate to invoices</div><div class="text-xs text-slate-500">Remaining: <b>{{money(remaining)}}</b></div></div><div v-for="i in openInvoices" :key="i.id" class="mb-2 flex items-center gap-3 rounded-xl bg-white p-3"><div class="flex-1"><div class="text-xs font-bold">{{i.invoice_number}}</div><div class="text-[10px] text-slate-400">Balance {{money(i.balance)}} · due {{i.due_date||'—'}}</div></div><MoneyInput v-model="allocationMap[i.id]" @update:model-value="clamp(i)" class="max-w-36" :min="0" :max="Number(i.balance)" /></div><div v-if="!openInvoices.length" class="empty py-6">Select a client with open invoices.</div></div><div class="mt-5 flex justify-end gap-2 border-t border-slate-100 pt-4"><button type="button" class="btn btn-soft" @click="open=false">Cancel</button><button class="btn btn-primary" :disabled="saving||!allocationComplete">{{saving?'Saving…':'Save payment'}}</button></div></form></AppModal><div v-if="error" class="fixed bottom-5 right-5 rounded-xl bg-rose-600 px-4 py-3 text-xs font-bold text-white shadow-xl">{{error}}</div></div></template>
<script setup lang="ts">import MoneyInput from '../../components/MoneyInput.vue';import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {api,apiError} from '../../services/api';import {useConfirm} from '../../stores/confirm';import {useToast} from '../../stores/toast';import AppModal from '../../components/AppModal.vue';const route=useRoute();const {ask:confirm}=useConfirm();const toast=useToast();const payments=ref<any[]>([]),clients=ref<any[]>([]),openInvoices=ref<any[]>([]),allocationMap=ref<any>({}),open=ref(false),saving=ref(false),error=ref('');const form=ref<any>({client_id:null,amount:0,method:'cash',reference:'',allocations:[]});const allocated=computed(()=>Object.values(allocationMap.value).reduce((s:any,v:any)=>s+Number(v||0),0));const remaining=computed(()=>Math.max(0,Number(form.value.amount||0)-allocated.value));const allocationComplete=computed(()=>Number(form.value.amount||0)>0&&Math.abs(remaining.value)<0.01);function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){payments.value=(await api.get('/payments',{params:{per_page:30}})).data.data}async function openCreate(){clients.value=(await api.get('/clients',{params:{per_page:100}})).data.data;form.value={client_id:route.query.client_id?Number(route.query.client_id):null,amount:0,method:'cash',reference:'',allocations:[]};allocationMap.value={};openInvoices.value=[];error.value='';open.value=true;if(form.value.client_id){await loadInvoices();if(route.query.invoice_id){const inv=openInvoices.value.find((x:any)=>x.id===Number(route.query.invoice_id));if(inv){form.value.amount=Number(inv.balance);allocationMap.value[inv.id]=Number(inv.balance)}}}}async function loadInvoices(){if(!form.value.client_id){openInvoices.value=[];return}const r=await api.get('/invoices',{params:{per_page:100,status:'partial'}});const r2=await api.get('/invoices',{params:{per_page:100,status:'issued'}});openInvoices.value=[...r.data.data,...r2.data.data].filter((x:any)=>x.client_id===form.value.client_id&&Number(x.balance)>0);allocationMap.value={}}function clamp(i:any){allocationMap.value[i.id]=Math.min(Math.max(0,Number(allocationMap.value[i.id]||0)),Number(i.balance))}async function save(){saving.value=true;error.value='';try{const allocations=Object.entries(allocationMap.value).filter(([,v])=>Number(v)>0).map(([invoice_id,amount])=>({invoice_id:Number(invoice_id),amount:Number(amount)}));form.value.allocations=allocations;if(!allocationComplete.value){error.value='Allocate the full payment amount before saving.';return}await api.post('/payments',form.value);open.value=false;await load();toast.success('Payment recorded','Payment was recorded and allocated successfully.')}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}finally{saving.value=false}}async function remove(p:any){if(!(await confirm({title:'Reverse payment?',message:`${p.payment_number} will be reversed and the affected invoice balances will be recalculated. This action cannot be undone.`,confirmText:'Reverse payment',danger:true})))return;try{await api.delete(`/payments/${p.id}`);await load();toast.success('Payment reversed', `${p.payment_number} was reversed successfully.`)}catch(e){error.value=apiError(e);toast.error('Action failed', apiError(e))}}onMounted(async()=>{await load();if(route.query.client_id)await openCreate()})</script>
